from gtts import gTTS
import os

def text_to_audio(text, filename="output.mp3", lang='en'):
    """
    Convert text to audio and save it as a file.

    Parameters:
      text: The text to convert.
      filename: The name of the output audio file (default: output.mp3).
      lang: The language of the text (default: 'en' for English).
    """
    try:
        # Create an audio object
        tts = gTTS(text=text, lang=lang)
        
        # Save the audio file
        tts.save(filename)
        print(f"Audio saved as {filename}")
        
        # Play the audio file (optional, works on supported OSes)
        os.system(f"start {filename}" if os.name == "nt" else f"open {filename}")
    except Exception as e:
        print(f"Error: {e}")

